from pathlib import Path
import re,sys
B=Path(__file__).parent;R=B.parent;sys.path.insert(0,str(B/'exam-rewrite'));import mathml
mathml.wrap_display=lambda s:s
def fo(x,y,w,h,formula):return f'<foreignObject x="{x}" y="{y}" width="{w}" height="{h}"><div xmlns="http://www.w3.org/1999/xhtml" style="display:flex;align-items:center;justify-content:center;height:100%;font-size:22px">'+mathml.render(formula,True)+'</div></foreignObject>'
first='''<figure class="boolean-diagram"><svg viewBox="0 0 760 360" xmlns="http://www.w3.org/2000/svg" role="img" aria-labelledby="boolean-selector-title boolean-selector-desc"><title id="boolean-selector-title">The actual selector reconstructions of x-prime y plus x z</title><desc id="boolean-selector-desc">Restrict x to zero to obtain y and x to one to obtain z. The two data cofactors connect to a mux whose select pin is x.</desc><g fill="#edf5f8" stroke="#8cb2c2"><rect x="35" y="72" width="230" height="69" rx="9"/><rect x="35" y="195" width="230" height="69" rx="9"/><path d="M380 66L470 92V233L380 260Z" fill="#fbf5e8"/></g><g fill="none" stroke="#438297" stroke-width="2"><path d="M265 107H380M265 230H380M470 163H695M425 287V247"/></g><g font-family="Source Sans 3" font-size="17" fill="#28495b"><text x="55" y="61">Restrict x to zero</text><text x="55" y="185">Restrict x to one</text><text x="390" y="112">0</text><text x="390" y="235">1</text><text x="488" y="139">Selected output</text><text x="447" y="281">select input</text></g>'''+fo(45,86,205,42,r'F_{x=0}=y')+fo(45,211,205,42,r'F_{x=1}=z')+fo(385,273,43,30,'x')+fo(492,168,205,51,r'F=(\neg x)y+xz')+'''</svg><figcaption>Figure 1. The actual function has zero cofactor y and one cofactor z. Connected data pins and the separately labeled select pin reconstruct it exactly; no gate-delay model is implied.</figcaption></figure>'''
second='''<figure class="boolean-diagram"><svg viewBox="0 0 760 350" xmlns="http://www.w3.org/2000/svg" role="img" aria-labelledby="boolean-proof-title boolean-proof-desc"><title id="boolean-proof-title">A complete miter proof for the OR distributive identity</title><desc id="boolean-proof-desc">The miter compares x OR yz with the product of x OR y and x OR z. Its x-zero cofactor is yz XOR yz and its x-one cofactor is one XOR one; both are zero.</desc><g fill="#edf5f8" stroke="#8cb2c2"><rect x="35" y="20" width="690" height="68" rx="9"/><rect x="275" y="109" width="210" height="48" rx="9"/><rect x="35" y="226" width="300" height="76" rx="9"/><rect x="425" y="226" width="300" height="76" rx="9"/></g><g fill="none" stroke="#438297" stroke-width="2"><path d="M380 88V109M380 157V183H185V226M380 183H575V226"/></g><circle cx="380" cy="183" r="3" fill="#438297"/><g font-family="Source Sans 3" font-size="17" fill="#28495b"><text x="301" y="140">Restrict the miter on x</text><text x="155" y="213">x = 0</text><text x="548" y="213">x = 1</text><text x="212" y="329">Both input slices vanish; every input is covered.</text></g>'''+fo(50,30,660,47,r'M=(x+yz)\oplus((x+y)(x+z))')+fo(50,242,270,46,r'M_{x=0}=yz\oplus yz=0')+fo(438,242,272,46,r'M_{x=1}=1\oplus1=0')+'''</svg><figcaption>Figure 2. This is the actual complete two-branch proof of x+yz=(x+y)(x+z). Both cofactors of its mismatch miter are zero, so the functions agree on the full binary domain.</figcaption></figure>'''
p=R/'dist/chapters/g_boolean.html';s=p.read_text(encoding='utf-8');i=0
def replace(m):
 global i
 v=[first,second][i];i+=1;return v
s=re.sub(r'<figure class="boolean-diagram">[\s\S]*?</figure>',replace,s);assert i==2
s=s.replace('font-family="SourceSans3"','font-family="Source Sans 3"').replace('font-family="STIXTwoMath"','font-family="STIX Two Math"')
s=s.replace('x="155" y="213"','x="135" y="213"').replace('x="548" y="213"','x="595" y="213"')
p.write_text(s,encoding='utf-8');print('Two actual functional diagrams rebuilt with connected ports and native mathematical labels.')
